#pragma once

// Material You theme generated by matugen (Linux).
// matugen renders the bundled template into PalettePath(),
// pixelGram watches that file and applies it as the current theme.
namespace PixelMatugen {

[[nodiscard]] bool Supported();

// Where matugen should write the generated palette.
[[nodiscard]] QString PalettePath();

// Where the bundled matugen template is exported for the user's config.
[[nodiscard]] QString TemplatePath();

// Snippet for ~/.config/matugen/config.toml.
[[nodiscard]] QString ConfigSnippet();

// Starts or stops watching, depending on the setting.
void Refresh();

} // namespace PixelMatugen
